const pptxgen = require("pptxgenjs");
const pres = new pptxgen();
pres.layout = "LAYOUT_WIDE"; // 13.333 x 7.5
pres.title = "Running & Deploying Concept Buddy";

const NAVY = "1E2761", ICE = "CADCFC", WHITE = "FFFFFF", INK = "1A1A2E",
  TINT = "F4F6FB", ORANGE = "F2A65A", MUTED = "5B6270";
const H = "Cambria", B = "Calibri", MONO = "Courier New";

const T = (s, text, o) => s.addText(text, { isTextBox: true, fontFace: B, color: INK, margin: 0, valign: "top", ...o });
const card = (s, x, y, w, h, fill = TINT) =>
  s.addShape(pres.shapes.ROUNDED_RECTANGLE, { x, y, w, h, fill: { color: fill }, line: { color: fill }, rectRadius: 0.08 });

function header(s, n, title) {
  s.background = { color: WHITE };
  s.addShape(pres.shapes.OVAL, { x: 0.6, y: 0.55, w: 0.5, h: 0.5, fill: { color: NAVY }, line: { color: NAVY } });
  T(s, String(n), { x: 0.6, y: 0.55, w: 0.5, h: 0.5, fontFace: H, fontSize: 18, bold: true, color: WHITE, align: "center", valign: "middle" });
  T(s, title, { x: 1.3, y: 0.5, w: 11.4, h: 0.6, fontFace: H, fontSize: 32, bold: true, color: NAVY, valign: "middle" });
}
const label = (s, text, x, y, w, color = MUTED) =>
  T(s, text.toUpperCase(), { x, y, w, h: 0.3, fontSize: 11, bold: true, color, charSpacing: 1 });
// rows of [code, description]
function kv(s, rows, x, y, w, codeW, rowH, opts = {}) {
  rows.forEach(([k, v], i) => {
    const yy = y + i * rowH;
    T(s, k, { x, y: yy, w: codeW, h: rowH, fontFace: MONO, fontSize: opts.codeSize || 13, bold: true, color: opts.codeColor || NAVY });
